import { EngagementSignals } from "./types";

/**
 * Raw per-user, per-period engagement signals.
 *
 * Deliberately constructed so that weightedV1 and weightedV2 (see
 * formulas.ts) rank users DIFFERENTLY for the same period:
 *
 *  - "dave" logs in constantly but rarely searches or edits his schedule.
 *  - "elle" barely logs in but searches heavily.
 *  - "carol" is a more balanced user, and in 2026-02 makes heavy use of the
 *    scheduler specifically.
 *
 * Under weightedV1 (which weights logins at face value and searches
 * lightly), dave ranks highest in 2026-01. Under weightedV2 (which
 * discounts logins and weights searches heavily), elle ranks highest for
 * the exact same period, using the exact same raw data. This is the point:
 * changing the formula changes who the "most active" users are, so losing
 * track of which formula produced a given score is a real correctness
 * problem, not just a bookkeeping nuisance.
 */
export const engagementSignals: EngagementSignals[] = [
  { userId: "dave", period: "2026-01", logins: 30, searches: 0, scheduleEdits: 0 },
  { userId: "elle", period: "2026-01", logins: 0, searches: 15, scheduleEdits: 0 },
  { userId: "carol", period: "2026-01", logins: 10, searches: 10, scheduleEdits: 2 },

  { userId: "dave", period: "2026-02", logins: 20, searches: 2, scheduleEdits: 1 },
  { userId: "elle", period: "2026-02", logins: 2, searches: 20, scheduleEdits: 0 },
  { userId: "carol", period: "2026-02", logins: 8, searches: 8, scheduleEdits: 8 },
];
